import generated from "../../../docs/demo/site-search.generated.json";

/**
 * Chapter 8 ("site search") test data for the sign-in-free test path only (#208).
 * These lines were generated by the model for the demo (docs/demo/README.md). Under decision
 * NO-BACKUP no stored text is shown to real users; this data is used only on /try, which shows
 * a "Test build" label. Server-side only: do not import from a client component.
 */
export type TestStory = {
  id: string;
  title: string;
  isTestData: true;
  backgroundCard: string;
  steps: { title: string; cards: string[] }[];
  pauseMessage: string;
  restReplies: string[];
  returnLine: string;
  closingLine: string;
};

type GeneratedCard = { kind: string; text: string };
type GeneratedChat = { chosen?: { reply?: string; checks?: { ok?: boolean } } };

export function loadTestStory(): TestStory {
  const steps = generated.steps.map((step) => ({
    title: step.title,
    cards: (step.cards as GeneratedCard[]).map((card) => card.text),
  }));
  const opening = (generated.steps[0].cards as GeneratedCard[]).find(
    (card) => card.kind === "opening",
  );
  if (!opening) throw new Error("Test data has no opening card for Step 1.");
  steps[0] = { ...steps[0], cards: steps[0].cards.filter((text) => text !== opening.text) };

  const restReplies = (generated.pause.chat as GeneratedChat[])
    .filter((turn) => turn.chosen?.checks?.ok && turn.chosen.reply)
    .map((turn) => turn.chosen!.reply!);

  return {
    id: generated.meta.story.id,
    title: generated.meta.story.title,
    isTestData: true,
    backgroundCard: opening.text,
    steps,
    pauseMessage: generated.pause.stuck.text,
    restReplies,
    returnLine: generated.pause.back.text,
    closingLine: generated.closing.smooth.text,
  };
}
